            frm.remove_custom_button("Mark Attendance");
            frm.remove_custom_button("Send Feedback");
            return;
        }

        // Otherwise add buttons normally (if you already have logic)
        if (!frm.is_new()) {
            frm.add_custom_button("Mark Attendance", () => {
