            });

            frm.add_custom_button("Send Feedback", () => {
                // your existing code
            });
        }
    }
});

frappe.ui.form.on('Budget', {
    refresh: function(frm) {

        let field = frm.get_field("budget_against");
        let options = field.df.options.split("\n");
        let cleaned_options = options.filter(opt => opt.trim() !== "");
        frm.set_df_property("budget_against", "options", cleaned_options.join("\n"));
        frm.refresh_field("budget_against");
    }
});

frappe.ui.form.on('Leave Allocation', {
    refresh: function(frm) {

        const remove_actions = () => {
            frm.page.wrapper
                .find('div.inner-group-button[data-label="Actions"]')
                .remove();
        };

        // run immediately
        remove_actions();

        // run again after toolbar render
        setTimeout(remove_actions, 100);
    }
});

frappe.listview_settings['Annual Report'] = {
    refresh: function(listview) {

        // prevent duplicate
        if (listview.export_docx_added) return;
        listview.export_docx_added = true;

        listview.page.add_action_item('Export DOCX', function() {

            let selected = listview.get_checked_items();

            if (!selected.length) {
                frappe.msgprint('Please select records');
                return;
            }

            let names = selected.map(d => d.name);

            frappe.call({
                method: 'nafed_erp.meeting_and_co_ordination.doctype.annual_report.annual_report.export_multiple_docx',
                args: {
                    doctype: listview.doctype,
                    docnames: JSON.stringify(names)
                },
                freeze: true,
                freeze_message: 'Generating DOCX...',
                callback: function(r) {
                    if (r.message) {
                        window.open(r.message);
                    }
                }
            });

        });
    }
};

