frappe.ui.form.on('Material Request', {
    refresh(frm) {
        toggle_fields(frm);
    },
    onload_post_render(frm) {
        toggle_fields(frm);
    },
    custom_division_code(frm) {
        toggle_fields(frm);
    },
    workflow_state(frm) {
        toggle_fields(frm);
    }
});

function toggle_fields(frm) {

    let fields = ["custom_quotation_based", "custom_tender_based"];

    let division = frm.doc.custom_division_code || "";
    let workflow = frm.doc.workflow_state || "";

    let allowed_states = [
        "Pending Approval",
        "Approved",
        "Rejected",
        "Completed"
    ];

    let show = false;


    if (!frm.is_new()) {
        show = division === "IT" && allowed_states.includes(workflow);
    }

    fields.forEach(f => {
        frm.set_df_property(f, "hidden", !show);
    });
}

frappe.ui.form.on('Employee Onboarding', {
    refresh: function(frm) {

        if (!frm.is_new()) {

            frm.add_custom_button('Send Onboarding Form', function() {

                let onboarding_link =
                    window.location.origin +

                    "/employee-onboarding-details-form/new?" +

                    "reference_onboarding=" + encodeURIComponent(frm.doc.name || "") +

                    "&job_applicant=" + encodeURIComponent(frm.doc.job_applicant || "") +

                    "&job_offer=" + encodeURIComponent(frm.doc.job_offer || "") +

                    "&company=" + encodeURIComponent(frm.doc.company || "") +

                    "&date_of_joining=" + encodeURIComponent(frm.doc.date_of_joining || "") +

                    "&onboarding_begins_on=" + encodeURIComponent(frm.doc.boarding_begins_on || "");
                frappe.msgprint(`
                    <div style="word-break: break-word;">

                        <b>Send this onboarding link to employee:</b>

                        <br><br>

                        <a href="${onboarding_link}" target="_blank">
                            ${onboarding_link}
                        </a>

                    </div>
                `);

            });

        }
    }
});

frappe.ui.form.on('Employee', {
