                employee: frm.doc.name
            });
        });
    }
});

frappe.ui.form.on('Employee', {

    refresh: function(frm) {

        if (frm.is_new() && frm.doc.job_applicant) {

            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Employee Onboarding",
                    filters: {
                        job_applicant: frm.doc.job_applicant
                    },
                    fieldname: ["name"]
                },
                callback: function(r) {

                    if (r.message && r.message.name) {

                        let onboarding = r.message.name;

                        frappe.call({
                            method: "frappe.client.get",
                            args: {
                                doctype: "Employee Onboarding Details",
                                filters: {
                                    reference_onboarding: onboarding
                                },
                                fieldname: [

                                    "employee_name",
                                    "aadhaar_number",
                                    "uan_number",
                                    "pan_number",
                                    "bank_name",
                                    "bank_account_no",
                                    "ifsc_code",

                                    "first_name",
                                    "middle_name",
                                    "last_name",
                                    "gender",

                                    "date_of_birth",

                                    "mobile",
                                    "personal_email",

                                    "emergency_contact_name",
                                    "emergency_phone",
                                    "relation",

                                    "current_address",
                                    "permanent_address",

                                    "marital_status",
                                    "religion",
                                    "blood_group",
                                    "mother_tongue",

                                    "job_applicant",
                                    "job_offer",
                                    "company",

                                    "date_of_joining",
                                    "onboarding_begins_on"

                                ]
                            },

                            callback: function(res) {

                                if (res.message) {

                                    // BASIC DETAILS

                                    frm.set_value("first_name", res.message.first_name);
                                    frm.set_value("middle_name", res.message.middle_name);
                                    frm.set_value("last_name", res.message.last_name);
                                    frm.set_value("gender", res.message.gender);


                                    frm.set_value("date_of_birth", res.message.date_of_birth);

                                    // DOCUMENTS

                                    frm.set_value("custom_aadhar_number", res.message.aadhaar_number);

                                    frm.set_value("custom_uan_number", res.message.uan_number);

                                    frm.set_value("pan_number", res.message.pan_number);

                                    // BANK DETAILS

                                    frm.set_value("bank_name", res.message.bank_name);

                                    frm.set_value("bank_ac_no", res.message.bank_account_no);

                                    frm.set_value("ifsc_code", res.message.ifsc_code);

                                    // CONTACT DETAILS

                                    frm.set_value("cell_number", res.message.mobile);

                                    frm.set_value("personal_email", res.message.personal_email);

                                    // EMERGENCY

                                    frm.set_value("person_to_be_contacted", res.message.emergency_contact_name);

                                    frm.set_value("emergency_phone_number", res.message.emergency_phone);

                                    frm.set_value("relation", res.message.relation);

                                    // ADDRESS

                                    frm.set_value("current_address", res.message.current_address);

                                    frm.set_value("permanent_address", res.message.permanent_address);

                                    // PERSONAL

                                    frm.set_value("marital_status", res.message.martial_status);

                                    frm.set_value("custom_religion_old", res.message.religion);

                                    frm.set_value("blood_group", res.message.blood_group);

                                    frm.set_value("custom_mother_tongue", res.message.mother_tongue);

                                    // JOINING

                                    frm.set_value("date_of_joining", res.message.date_of_joining);

                                    frappe.msgprint("Employee details filled successfully.");

                                }

                            }
                        });

                    }

                }
            });

        }

    }

});
